function dir$t311(p){
  this.constructor(p);
}
dir$t311.prototype = new DirEvent();
dir$t311.prototype.beforeInit = function(renderType){
  this._dir.options._files = null;
  document._dir = this._dir;
}
dir$t311.prototype.afterInit = function(renderType){
  var p = this._dir, g = p.grid(0),g2 = p.grid(1);
  var exp = {
	tong_trong: ['*tong_trong', '[so_luong]*[ty_trong]'],
	tong_khoi: ['*tong_khoi', '[so_luong]*[ty_khoi]'],


    t_so_luong: ['@t_so_luong', '[so_luong]'],
  }
  p.applyExpression(exp, g, false);

  g.FomulaApplied = {
	"!ty_gia":[],
    "so_luong":["t_so_luong"],

	"ma_cong":["t_so_luong"],
  }
  //console.log(JSON.stringify(g.FomulaApplied)); //Gan la ds cong thuc tinh cho cot nao do: 


  p.options.FCColumns = {FC: [], BC: []};
  g.FCColumns = {FC: [], BC: []};

  var oldTG = '', oTG = p.jObject('ma_nt'); //Neu ty gia thay doi
  oTG.focus(function(){ oldTG = oTG.fval(); }).blur(function(){ if (oldTG != oTG.fval()) onExRateChanged(oTG, p);});
  p.applyFCColumns();
  p.applyFCColumns(g);
 // p.setFCHidden(oTG.fval());

  dir$t311DisabledMasterField(p, g);
  dir$t311HiddenColumnByType(p);
  dir$t311HiddenColumnByTran(p);
  dir$t311DisabledMasterPort(p);
  dir$t311DisabledStatusByAction(p);
  //dir$t311LoadDataQuote(p);
  p.find(".control-label.t_so_luong, .control-label.t_tien_nt2, .control-label.t_thue_nt, .control-label.t_tt_nt, .input-field.t_so_luong, .input-field.t_tien_nt2, .input-field.t_tien2, .input-field.t_thue_nt, .input-field.t_thue, .input-field.t_tt_nt, .input-field.t_tt").css("font-weight", "bold");

}

dir$t311.prototype.beforeButtonDialogClick = function (id) {
  var p = this._dir, g = p.grid(0), dt = g.data;
  switch (id) {
    case 'ok':
		var d = p.valForm('ngay_hl'),d2 = p.valForm('ngay_hld');
		var k = $.date(d,"dd/mm/yy"),k2 = $.date(d2,"dd/mm/yy");
		if (p.valForm('ngay_hld') <= p.valForm('ngay_hl')) { 
			<!-- $.question('jkhj '+'Nhap sai ngay ??' ); -->
			<!-- $.showToast(p.msg('noDate')); -->

			$.alert(p.msg('noDate')+' ' + k + ' < ' + k2);			
			return false;
			Break;
			}	  		  
    default:
      break;
  }
  return true;
}
dir$t311.prototype.beforeButtonGridClick = function (id, gindex) {

  var p = this._dir;
  switch (id) {
  	case '10':

      p.showFilter("t311TC0", null, {_ngay_ct: p.valForm('ngay_ct'),_ngay_ct1: p.valForm('ngay_hl'),_ngay_ct2: p.valForm('ngay_hld')});	  
	  return false;
      break;

    default:
      break;
  }
  return true;
}

dir$t311.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
&VoucherExRateValid01;
    case 'ma_gd':
      dir$t311HiddenColumnByTran(p);
      break;
    case 'ma_ngv':
      dir$t311HiddenColumnByType(p);
      break;
    case 'ty_gia':
      p.calcExpressionAll(0, '!ty_gia');
      break;
	case 'ma_dk_ngay':
      dir$t311HiddenColumnByDay(p);
	   break;
	case 'unit_id':
	 dir$t311DisabledMasterField(p, g);
      break;
	  case 'id_bg':
	 dir$t311DisabledMasterPort(p);
      break;
    default:
      break;
  }
}


dir$t311.prototype.gridCellValueChange = function (o, g, r, c, v) {
 var p = this._dir;
  switch (c){


    case 'ma_nt':
		p.request('GetExRateDetail', '', ['ma_nt', '!ngay_ct']);
		p.grequest(g, 'GetExRateDetail', '', ['ma_nt', '!ngay_ct'], null, r);
      break;



    default:
      break;
  }
}

&VoucherExRateValid02;
dir$t311.prototype.gridDetailActionChange = function(gindex, action, r){
  var p = this._dir;
  if (action == 'AfterDeleteRow' || action == 'AfterAppendGrid') dir$t311DisabledMasterField(p, p.grid(gindex));
  return true;
}
