function dir$t311DisabledMasterField(p, g){
if (p.options.action !="NEW")
 p.setDisabled(['so_ct','ngay_ct', 'ma_nt','ma_gd','ma_nv','ma_ngv'], true);

}
function dir$t311HiddenColumnByType(p){
  var v = p.valForm('ma_ngv'), nt = p.valForm('ma_nt'), bc = p.options.struct.baseCurrency;
  var date = new Date();
}
function dir$t311HiddenColumnByTran(p){
	var gd = p.valForm('ma_gd').trim();

